function loadTxt(path) {
  return fs
    .readFileSync(path, "utf8")
    .trim()
    .split("\n")
    .map((line) => {
      const i = line.indexOf("\t");
      return { id: line.slice(0, i) };
    });
}

for (const [num, path, table] of [
  [4, "/tmp/beishi027-batch4.txt", T4],
  [5, "/tmp/beishi027-batch5.txt", T5],
  [6, "/tmp/beishi027-batch6.txt", T6],
]) {
  const rows = loadTxt(path);
  const arr = rows.map(({ id }) => {
    const pair = table[id];
    if (!pair) throw new Error(`Missing ${id} batch ${num}`);
    return { id, literal: pair[0], idiomatic: pair[1] };
  });
  const out = `/workspace/translations/patches/beishi-027-batch${num}.json`;
  fs.writeFileSync(out, JSON.stringify(arr, null, 2) + "\n");
  console.log(`${out}: ${arr[0].id} .. ${arr[arr.length - 1].id} (${arr.length})`);
}
